1	package cli
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"io"
8		"net/url"
9		"os/exec"
10		"sort"
11		"strconv"
12		"strings"
13		"time"
14	
15		"charm.land/bubbles/v2/key"
16		tea "charm.land/bubbletea/v2"
17		"charm.land/huh/v2"
18		"charm.land/lipgloss/v2"
19		"github.com/spf13/cobra"
20	
21		"github.com/entireio/cli/cmd/entire/cli/agent"
22		"github.com/entireio/cli/cmd/entire/cli/agent/external"
23		"github.com/entireio/cli/cmd/entire/cli/agent/types"
24		"github.com/entireio/cli/cmd/entire/cli/api"
25		"github.com/entireio/cli/cmd/entire/cli/auth"
26		"github.com/entireio/cli/cmd/entire/cli/gitremote"
27		"github.com/entireio/cli/cmd/entire/cli/palette"
28		"github.com/entireio/cli/cmd/entire/cli/paths"
29		"github.com/entireio/cli/cmd/entire/cli/uiform"
30		"github.com/entireio/cli/internal/coreapi"
31	)
32	
33	var (
34		errConfigureGHUnavailable     = errors.New("gh CLI is not installed")
35		errConfigureGHUnauthenticated = errors.New("gh CLI is not authenticated")
36	)
37	
38	const (
39		configureAccessPollInterval = 2 * time.Second
40		configureAccessWaitTimeout  = 5 * time.Minute
41		configureCommitMessage      = "chore: configure entire"
42		configureBranchBase         = "configure-entire"
43		configureSaveDirect         = "direct"
44		configureSaveNewBranch      = "new-branch"
45		configureSaveLocal          = "local"
46		configureSaveCancel         = "cancel"
47	)
48	
49	// configureAccessReporter is the small part of the authenticated API used by
50	// onboarding. Keeping it narrow makes the state machine independently testable.
51	type configureAccessReporter interface {
52		ReportEnable(ctx context.Context, remoteURL string) (*api.EnableRepoResponse, error)
53	}
54	
55	// configureFlowDeps contains side effects used by the interactive configure
56	// flow. Tests can replace individual operations without a keyring, browser,
57	// GitHub CLI, or live control plane.
58	type configureFlowDeps struct {
59		resolveAuth  func(context.Context) (statusTarget, error)
60		fetchProfile profileFetcher
61		runLogin     func(context.Context, io.Writer, io.Writer) error
62		accessClient func(context.Context) (configureAccessReporter, error)
63		coreClient   func() (*coreapi.Client, error)
64		openURL      browserOpenFunc
65		githubAdmin  func(context.Context, string, string) (bool, error)
66		now          func() time.Time
67	}
68	
69	func newConfigureFlowDeps(insecure bool) configureFlowDeps {
70		return configureFlowDeps{
71			resolveAuth: func(ctx context.Context) (statusTarget, error) {
72				return resolveAuthStatusTarget(ctx, auth.Contexts, auth.RefreshedLoginToken)
73			},
74			fetchProfile: defaultFetchProfile,
75			runLogin: func(ctx context.Context, outW, errW io.Writer) error {
76				cmd := newLoginCmd()
77				cmd.SetContext(ctx)
78				cmd.SetOut(outW)
79				cmd.SetErr(errW)
80				return cmd.RunE(cmd, nil)
81			},
82			accessClient: func(ctx context.Context) (configureAccessReporter, error) {
83				return NewAuthenticatedAPIClient(ctx, insecure)
84			},
85			coreClient:  coreapi.New,
86			openURL:     openBrowser,
87			githubAdmin: configureGitHubAdmin,
88			now:         time.Now,
89		}
90	}
91	
92	// runConfigureOnboarding is a seam for command tests. Bare interactive
93	// `entire configure` is the new end-to-end entry point; flag-based configure
94	// remains the non-interactive settings editor.
95	var runConfigureOnboarding = func(cmd *cobra.Command, opts EnableOptions) error {
96		return runConfigureOnboardingFlow(cmd, opts, newConfigureFlowDeps(false))
97	}
98	
99	func runConfigureOnboardingFlow(cmd *cobra.Command, opts EnableOptions, deps configureFlowDeps) error {
100		cmd.SilenceUsage = true
101		ctx := cmd.Context()
102		outW, errW := cmd.OutOrStdout(), cmd.ErrOrStderr()
103	
104		repoRoot, err := paths.WorktreeRoot(ctx)
105		if err != nil {
106			fmt.Fprintln(errW, "Not a git repository. Please run 'entire configure' from within a git repository.")
107			return NewSilentError(errors.New("not a git repository"))
108		}
109		owner, repo, cleanRemote, err := configureRepoIdentity(ctx)
110		if err != nil {
111			return err
112		}
113	
114		profile, err := ensureConfigureLogin(ctx, outW, errW, deps)
115		if err != nil {
116			return err
117		}
118	
119		reporter, err := deps.accessClient(ctx)
120		if err != nil {
121			return fmt.Errorf("connect to Entire: %w", err)
122		}
123		access, err := reporter.ReportEnable(ctx, cleanRemote)
124		if err != nil {
125			return fmt.Errorf("check repository access: %w", err)
126		}
127		if !access.Connected {
128			if err := ensureConfigureRepoAccess(ctx, outW, errW, reporter, access, cleanRemote, owner, repo, deps); err != nil {
129				return err
130			}
131		}
132	
133		client, err := deps.coreClient()
134		if err != nil {
135			return fmt.Errorf("connect to Entire control plane: %w", err)
136		}
137		placements, err := resolvePullablePlacements(ctx, client, owner, repo)
138		if err != nil {
139			return renderCoreError(err)
140		}
141		if len(placements) == 0 {
142			placements, err = configureCreateMirrors(ctx, outW, errW, client, owner, repo, profile.Jurisdiction)
143			if err != nil {
144				return err
145			}
146		}
147		if len(placements) == 0 {
148			return errors.New("no usable mirror was selected")
149		}
150	
151		manageRegionsHint := ""
152		if admin, adminErr := deps.githubAdmin(ctx, owner, repo); adminErr == nil && admin {
153			manageRegionsHint = fmt.Sprintf("Manage regions: entire repo mirror create · or %s/gh/%s/%s/settings",
154				configureWebBaseURL(), url.PathEscape(owner), url.PathEscape(repo))
155		}
156		before, err := configureGitChanges(ctx, repoRoot)
157		if err != nil {
158			return err
159		}
160		branch, branchErr := gitRunner(ctx, repoRoot, "branch", "--show-current")
161		if branchErr != nil {
162			// Best-effort: local-only saves do not need a branch.
163			branch = ""
164		}
165		protected := false
166		if branch != "" {
167			if detected, protectionErr := configureBranchProtected(ctx, owner, repo, branch); protectionErr == nil {
168				// Advisory only; git push remains authoritative.
169				protected = detected
170			}
171		}
172		chosen, selectedAgents, saveChoice, agentsChanged, err := promptConfigureUpstreamAndAgents(
173			ctx, errW, repoRoot, placements, profile.Jurisdiction, manageRegionsHint,
174			branch, protected, len(before) == 0,
175		)
176		if err != nil {
177			return err
178		}
179		if saveChoice == configureSaveCancel {
180			fmt.Fprintln(outW, "Configuration cancelled.")
181			return nil
182		}
183		if saveChoice == "" {
184			fmt.Fprintln(outW, "No configuration changes.")
185			return nil
186		}
187		if err := configureUseMirror(ctx, repoRoot, owner, repo, chosen); err != nil {
188			return err
189		}
190	
191		if agentsChanged {
192			opts = configureOnboardingEnableOptions(opts)
193			if err := runEnableInteractive(ctx, outW, selectedAgents, opts); err != nil {
194				return err
195			}
196			// A local enabled:false override must not win over the newly written project
197			// configuration. setEnabledFlag updates the project and synchronizes an
198			// existing local override without replacing its other local-only fields.
199			if err := setEnabledFlag(ctx, true, true); err != nil {
200				return err
201			}
202		}
203	
204		after, err := configureGitChanges(ctx, repoRoot)
205		if err != nil {
206			return err
207		}
208		generated := newConfigureChanges(before, after)
209		if agentsChanged {
210			fmt.Fprintf(outW, "✓ Wrote %s\n", configDisplayProject)
211		}
212	
213		if saveChoice == configureSaveDirect || saveChoice == configureSaveNewBranch {
214			if err := configureSaveAndPush(cmd, repoRoot, owner, repo, before, generated, branch, protected, saveChoice, deps.now); err != nil {
215				return err
216			}
217		} else if agentsChanged && len(generated) > 0 {
218			fmt.Fprintln(outW, "  Configuration was saved locally. Review and commit it normally when ready.")
219		}
220		fmt.Fprintln(outW, "✓ Configuration complete")
221		fmt.Fprintln(outW)
222		fmt.Fprintln(outW, "  You're set. Start a session with any selected agent —")
223		fmt.Fprintf(outW, "  checkpoints will show up on %s/gh/%s/%s\n", configureWebBaseURL(), url.PathEscape(owner), url.PathEscape(repo))
224		return nil
225	}
226	
227	func configureOnboardingEnableOptions(opts EnableOptions) EnableOptions {
228		opts.Yes = true
229		opts.UseProjectSettings = true
230		opts.UseLocalSettings = false
231		opts.SuppressDoneMessage = true
232		opts.SuppressAdditionalSetup = true
233		// Login already establishes the user's account context, so this flow does
234		// not ask for or modify repository-local anonymous telemetry consent.
235		return opts
236	}
237	
238	func configureWebBaseURL() string {
239		return strings.TrimRight(api.BaseURL(), "/")
240	}
241	
242	func configureRepoIdentity(ctx context.Context) (owner, repo, cleanRemote string, err error) {
243		raw, err := gitremote.GetRemoteURL(ctx, defaultMirrorRemote)
244		if err != nil {
245			return "", "", "", fmt.Errorf("read origin remote: %w", err)
246		}
247		info, err := gitremote.ParseURL(raw)
248		if err != nil {
249			return "", "", "", fmt.Errorf("parse origin remote: %w", err)
250		}
251		if info.Forge != mirrorUseForge {
252			return "", "", "", errors.New("interactive configure currently requires a GitHub origin remote")
253		}
254		clean, err := cleanRemoteURLForReport(raw)
255		if err != nil {
256			return "", "", "", err
257		}
258		return strings.ToLower(info.Owner), strings.ToLower(info.Repo), clean, nil
259	}
