261	func ensureConfigureLogin(ctx context.Context, outW, errW io.Writer, deps configureFlowDeps) (*authProfile, error) {
262		target, err := deps.resolveAuth(ctx)
263		if err != nil {
264			return nil, err
265		}
266		if target.token != "" {
267			if profile, profileErr := deps.fetchProfile(ctx, target.coreURL, target.token); profileErr == nil {
268				return profile, nil
269			} else if !isKeychainTokenRejected(profileErr) {
270				return nil, fmt.Errorf("validate login: %w", profileErr)
271			}
272		}
273	
274		if err := deps.runLogin(ctx, outW, errW); err != nil {
275			return nil, fmt.Errorf("login: %w", err)
276		}
277		target, err = deps.resolveAuth(ctx)
278		if err != nil {
279			return nil, err
280		}
281		if target.token == "" {
282			return nil, errors.New("login completed without an active session")
283		}
284		profile, err := deps.fetchProfile(ctx, target.coreURL, target.token)
285		if err != nil {
286			return nil, fmt.Errorf("validate login: %w", err)
287		}
288		fmt.Fprintf(outW, "✓ Logged in as %s\n", profile.Handle)
289		return profile, nil
290	}
