292	func ensureConfigureRepoAccess(ctx context.Context, outW, errW io.Writer, reporter configureAccessReporter, initial *api.EnableRepoResponse, cleanRemote, owner, repo string, deps configureFlowDeps) error {
293		fmt.Fprintf(errW, "✗ Entire has no access to %s/%s\n\n", owner, repo)
294		installURL := strings.TrimSpace(initial.InstallURL)
295		if installURL == "" {
296			installURL = fmt.Sprintf("%s/install?repo=%s%%2F%s", configureWebBaseURL(), url.PathEscape(owner), url.PathEscape(repo))
297		}
298	
299		admin, adminErr := deps.githubAdmin(ctx, owner, repo)
300		if adminErr == nil && !admin {
301			fmt.Fprintln(errW, "  An admin needs to install the GitHub app first.")
302			fmt.Fprintln(errW, "  Send them this link to continue:")
303			fmt.Fprintf(errW, "\n  %s\n", installURL)
304			return NewSilentError(errors.New("GitHub app installation required"))
305		}
306		if adminErr != nil {
307			switch {
308			case errors.Is(adminErr, errConfigureGHUnavailable):
309				fmt.Fprintln(errW, "  Could not verify GitHub admin access because the gh CLI is not installed.")
310				fmt.Fprintln(errW, "  Install it from https://cli.github.com/ and run `gh auth login` for future checks.")
311			case errors.Is(adminErr, errConfigureGHUnauthenticated):
312				fmt.Fprintln(errW, "  Could not verify GitHub admin access because the gh CLI is not authenticated.")
313				fmt.Fprintln(errW, "  Run `gh auth login` for future checks.")
314			default:
315				fmt.Fprintf(errW, "  Could not verify GitHub admin access: %v\n", adminErr)
316			}
317			fmt.Fprintln(errW, "  If you administer this repository, you can still continue with the installation link.")
318			fmt.Fprintln(errW)
319		}
320	
321		fmt.Fprintln(outW, "  Install the GitHub app to grant access:")
322		fmt.Fprintf(outW, "  %s\n\n", installURL)
323		if err := deps.openURL(ctx, installURL); err != nil {
324			fmt.Fprintln(outW, "  Open the link above in your browser.")
325		}
326		stop := startSpinner(errW, "Waiting for installation")
327		stopped := false
328		defer func() {
329			if !stopped {
330				stop(false)
331			}
332		}()
333	
334		waitCtx, cancel := context.WithTimeout(ctx, configureAccessWaitTimeout)
335		defer cancel()
336		ticker := time.NewTicker(configureAccessPollInterval)
337		defer ticker.Stop()
338		for {
339			select {
340			case <-waitCtx.Done():
341				return fmt.Errorf("waiting for GitHub app installation: %w", waitCtx.Err())
342			case <-ticker.C:
343				access, err := reporter.ReportEnable(waitCtx, cleanRemote)
344				if err == nil && access.Connected {
345					stop(true)
346					stopped = true
347					fmt.Fprintln(outW, "✓ Access granted")
348					return nil
349				}
350			}
351		}
352	}
