354	func configureGitHubAdmin(ctx context.Context, owner, repo string) (bool, error) {
355		runner := execRunner{}
356		if !ghAvailable(ctx, runner) {
357			return false, errConfigureGHUnavailable
358		}
359		if !ghAuthenticated(ctx, runner) {
360			return false, errConfigureGHUnauthenticated
361		}
