404	func pickConfigureRegions(ctx context.Context, outW io.Writer, regions []regionChoice, jurisdiction string) ([]regionChoice, error) {
405		opts, defaults := clusterChoices(regions, jurisdiction)
406		byHost := make(map[string]regionChoice, len(regions))
407		for _, region := range regions {
408			byHost[region.host] = region
409		}
410		selected := append([]string(nil), defaults...)
411		form := NewAccessibleForm(huh.NewGroup(
412			huh.NewMultiSelect[string]().
413				Title("Which regions should this repository live in?").
414				Description("Space to select, enter to confirm — your data stays in the selected regions.").
415				Options(opts...).
416				Height(multiSelectHeight(len(opts))).
417				Validate(func(values []string) error {
418					if len(values) == 0 {
419						return errors.New("select at least one region")
420					}
421					return nil
422				}).
423				Value(&selected),
424		))
425		if err := form.RunWithContext(ctx); err != nil {
