660	func sameStrings(a, b []string) bool {
661		if len(a) != len(b) {
662			return false
663		}
664		seen := make(map[string]int, len(a))
665		for _, value := range a {
666			seen[value]++
667		}
668		for _, value := range b {
669			seen[value]--
670			if seen[value] < 0 {
671				return false
672			}
673		}
674		return true
675	}
