681			if help.Key == "enter" && help.Desc == "select" {
682				bindings[i].SetHelp("enter", "continue")
683			}
684		}
685		return append(bindings, key.NewBinding(key.WithKeys("space"), key.WithHelp("space", "select")))
686	}
