696	// promptConfigureUpstreamAndAgents presents upstream, agents, and the dynamic
697	// save action as one persistent form. Save stays hidden until a choice differs
698	// from the repository's current state. Arrow keys stay within the active
699	// section; Enter advances, while shift+tab revisits the previous section.
700	func promptConfigureUpstreamAndAgents(ctx context.Context, errW io.Writer, repoRoot string, placements []coreapi.ResolvedPlacement, jurisdiction, manageRegionsHint, branch string, protected, cleanWorktree bool) (coreapi.ResolvedPlacement, []agent.Agent, string, bool, error) {
701		currentHost := configureCurrentUpstream(ctx, repoRoot)
702		placements = configurePlacementOrder(placements, currentHost, jurisdiction)
703		if len(placements) == 0 {
704			return coreapi.ResolvedPlacement{}, nil, "", false, errors.New("no upstreams available")
705		}
706	
707		// configurePlacementOrder puts the configured upstream first, so it is also
708		// the initial selection. If this repo has no Entire upstream yet, it falls
709		// back to the jurisdiction-preferred placement.
710		selectedHost := placements[0].ClusterHost
711		placementByHost := make(map[string]coreapi.ResolvedPlacement, len(placements))
712		for _, placement := range placements {
713			placementByHost[placement.ClusterHost] = placement
714		}
715		upstreamOptions := func() []huh.Option[string] {
716			return configureUpstreamOptions(placements, selectedHost, currentHost)
717		}
718	
719		external.DiscoverAndRegisterAlways(ctx)
720		preselected := configureAgentPreselection(ctx)
721		agentOptions := configureAgentOptions(hookAgentOptions(preselected), preselected)
722		if len(agentOptions) == 0 {
723			return coreapi.ResolvedPlacement{}, nil, "", false, errors.New("no agents with hook support available")
724		}
725		installedAgentNames := make([]string, 0)
726		for _, name := range GetAgentsWithHooksInstalled(ctx) {
727			installedAgentNames = append(installedAgentNames, string(name))
728		}
729		selectedAgentNames := make([]string, 0, len(preselected))
730		for _, option := range agentOptions {
731			if _, ok := preselected[types.AgentName(option.Value)]; ok {
732				selectedAgentNames = append(selectedAgentNames, option.Value)
733			}
734		}
735	
736		// huh's footer already documents navigation. Keep field descriptions for
737		// contextual information only, rather than repeating keyboard controls.
738		upstreamDescription := manageRegionsHint
739		upstreamControl := &configureUpstreamField{
740			value:       &selectedHost,
741			committed:   selectedHost,
742			highlighted: selectedHost,
743		}
744		upstreamControl.Select = huh.NewSelect[string]().
745			TitleFunc(func() string {
746				return configureQuestionTitle("Which upstream do you want to use?", upstreamControl.focused)
747			}, &upstreamControl.focused).
748			Description(upstreamDescription).
749			Options(upstreamOptions()...).
750			Height(configureFieldHeight(len(placements), upstreamDescription)).
751			Value(&selectedHost)
752		upstreamControl.refresh = func() {
753			upstreamControl.Options(upstreamOptions()...)
754		}
755	
756		agentControl := &configureAgentField{value: &selectedAgentNames}
757		agentControl.MultiSelect = huh.NewMultiSelect[string]().
758			TitleFunc(func() string {
759				return configureQuestionTitle("Select the agents you want to use", agentControl.focused)
760			}, &agentControl.focused).
761			Options(agentOptions...).
762			// MultiSelect subtracts its title from an implicit viewport height, so
763			// include exactly one title row to show every option without padding.
764			Height(len(agentOptions) + 1).
765			Validate(func(values []string) error {
766				if len(values) == 0 {
767					return errors.New("select at least one agent")
768				}
769				return nil
770			}).
771			Value(&selectedAgentNames)
772	
773		mirrorChanged := func() bool {
774			mirror, _ := configureSelectionChanges(selectedHost, currentHost, selectedAgentNames, installedAgentNames)
775			return mirror
776		}
777		agentsChanged := func() bool {
778			_, agents := configureSelectionChanges(selectedHost, currentHost, selectedAgentNames, installedAgentNames)
779			return agents
780		}
781		requiresPush := func() bool {
782			return agentsChanged() && cleanWorktree && branch != ""
783		}
784		hasChanges := func() bool {
785			return mirrorChanged() || agentsChanged()
786		}
787	
788		saveChoice := defaultConfigureSaveChoice(requiresPush(), protected)
789		saveControl := &configureSaveField{
790			value:       &saveChoice,
791			committed:   saveChoice,
792			highlighted: saveChoice,
793			hidden: func() bool {
794				return !hasChanges()
795			},
796		}
797		saveOptions := func() []huh.Option[string] {
798			return configureSaveOptions(branch, protected, requiresPush(), saveChoice)
799		}
800		saveControl.Select = huh.NewSelect[string]().
801			TitleFunc(func() string {
802				return configureQuestionTitle("Save configuration", saveControl.focused)
803			}, &saveControl.focused).
804			Description(configureSaveDescription(branch, protected, requiresPush())).
805			Options(saveOptions()...).
806			Height(configureFieldHeight(len(saveOptions()), configureSaveDescription(branch, protected, requiresPush()))).
807			Value(&saveChoice)
808		refreshSave := func() {
809			options := saveOptions()
810			if !configureOptionsContain(options, saveChoice) {
811				saveChoice = defaultConfigureSaveChoice(requiresPush(), protected)
812				saveControl.committed = saveChoice
813				saveControl.highlighted = saveChoice
814				options = saveOptions()
815			}
816			saveControl.Select.
817				Description(configureSaveDescription(branch, protected, requiresPush())).
818				Height(configureFieldHeight(len(options), configureSaveDescription(branch, protected, requiresPush()))).
819				Options(options...)
820		}
821		saveControl.refresh = refreshSave
822		upstreamControl.layoutChanged = refreshSave
823		agentControl.selectionChanged = refreshSave
824		agentControl.showSave = hasChanges
825	
826		group := huh.NewGroup(upstreamControl, agentControl, saveControl)
827		form := newConfigureForm(group)
828		// Separate the form from the shell prompt or preceding onboarding status.
829		fmt.Fprintln(errW)
830		if err := form.RunWithContext(ctx); err != nil {
831			if cancelErr := handleFormCancellation(errW, "Configure", err); cancelErr != nil {
832				return coreapi.ResolvedPlacement{}, nil, "", false, cancelErr
833			}
834			return coreapi.ResolvedPlacement{}, nil, "", false, NewSilentError(errors.New("configure cancelled"))
835		}
836	
837		chosen, ok := placementByHost[selectedHost]
838		if !ok {
839			return coreapi.ResolvedPlacement{}, nil, "", false, errors.New("selected upstream is no longer available")
840		}
841		selectedAgents := make([]agent.Agent, 0, len(selectedAgentNames))
842		for _, name := range selectedAgentNames {
843			ag, err := agent.Get(types.AgentName(name))
844			if err != nil {
845				return coreapi.ResolvedPlacement{}, nil, "", false, fmt.Errorf("load selected agent %q: %w", name, err)
846			}
847			selectedAgents = append(selectedAgents, ag)
848		}
849		if !hasChanges() {
850			saveChoice = ""
851		}
852		return chosen, selectedAgents, saveChoice, agentsChanged(), nil
853	}
854	
855	func configureUpstreamOptions(placements []coreapi.ResolvedPlacement, selectedHost, currentHost string) []huh.Option[string] {
856		options := make([]huh.Option[string], 0, len(placements))
857		for _, placement := range placements {
858			selected := placement.ClusterHost == selectedHost
859			label := configureRadioLabel(configurePlacementLabel(placement), selected)
860			if strings.EqualFold(placement.ClusterHost, currentHost) {
861				tag := lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Muted)).Render("— current")
862				label += " " + tag
863			}
864			options = append(options, huh.NewOption(label, placement.ClusterHost))
