1086			current, err = gitremote.GetRemoteURLInDir(ctx, repoRoot, defaultMirrorRemote)
1087			if err != nil {
1088				return fmt.Errorf("read origin remote URL: %w", err)
1089			}
1090		}
1091		mirrorURL := mirrorCloneURL(chosen.ClusterHost, owner, repo)
1092		preserve := defaultMirrorUpstreamRemote
1093		// An existing forge alias already preserves direct GitHub access. Avoid
1094		// manufacturing another alias, and never preserve an old Entire placement
1095		// under the misleading name "upstream".
1096		if info, parseErr := gitremote.ParseURL(current); parseErr == nil && info.Protocol == gitremote.ProtocolEntire {
