1103	// configureGitChanges returns porcelain status keyed by path. Its values retain
1104	// XY so callers can detect whether anything was already staged before the flow.
1105	func configureGitChanges(ctx context.Context, repoRoot string) (map[string]string, error) {
1106		out, err := gitRunner(ctx, repoRoot, "status", "--porcelain=v1", "--untracked-files=all")
1107		if err != nil {
1108			return nil, fmt.Errorf("read git status: %w", err)
1109		}
1110		changes := make(map[string]string)
1111		for _, line := range strings.Split(out, "\n") {
1112			if len(line) < 4 {
1113				continue
1114			}
1115			path := strings.TrimSpace(line[3:])
1116			if arrow := strings.LastIndex(path, " -> "); arrow >= 0 {
1117				path = path[arrow+4:]
1118			}
1119			if path != "" {
1120				changes[path] = line[:2]
1121			}
1122		}
1123		return changes, nil
1124	}
