1137	func configureSaveAndPush(cmd *cobra.Command, repoRoot, owner, repo string, before map[string]string, generated []string, branch string, protected bool, choice string, now func() time.Time) error {
1138		outW := cmd.OutOrStdout()
1139		if len(generated) == 0 {
1140			fmt.Fprintln(outW, "  No new configuration changes to commit.")
1141			return nil
1142		}
1143		if len(before) != 0 {
1144			fmt.Fprintln(outW, "  Configuration was saved but not committed because the worktree already had changes.")
1145			fmt.Fprintln(outW, "  Review and commit the configuration normally when ready.")
1146			return nil
1147		}
1148	
1149		if branch == "" {
1150			return errors.New("cannot save configuration from a detached HEAD")
1151		}
1152		if protected && choice == configureSaveDirect {
1153			return fmt.Errorf("%s is protected; push to a new branch", branch)
1154		}
1155		if choice != configureSaveDirect && choice != configureSaveNewBranch {
1156			return fmt.Errorf("unknown save choice %q", choice)
1157		}
1158	
1159		pushBranch := branch
1160		if choice == configureSaveNewBranch {
1161			var err error
1162			pushBranch, err = availableConfigureBranch(cmd.Context(), repoRoot, now)
1163			if err != nil {
1164				return err
1165			}
1166			if _, err := gitRunner(cmd.Context(), repoRoot, "switch", "-c", pushBranch); err != nil {
1167				return fmt.Errorf("create configuration branch: %w", err)
1168			}
1169		}
1170	
1171		args := []string{"add", "--"}
1172		args = append(args, generated...)
1173		if _, err := gitRunner(cmd.Context(), repoRoot, args...); err != nil {
1174			return fmt.Errorf("stage configuration: %w", err)
1175		}
1176		if _, err := gitRunner(cmd.Context(), repoRoot, "commit", "-m", configureCommitMessage); err != nil {
1177			return fmt.Errorf("commit configuration: %w", err)
1178		}
1179		sha, err := gitRunner(cmd.Context(), repoRoot, "rev-parse", "--short", "HEAD")
1180		if err != nil {
1181			return fmt.Errorf("read configuration commit: %w", err)
1182		}
1183		fmt.Fprintf(outW, "✓ Committed %s · %s\n", configureCommitMessage, sha)
1184		if _, err := gitRunner(cmd.Context(), repoRoot, "push", "-u", defaultMirrorRemote, pushBranch); err != nil {
1185			return fmt.Errorf("push configuration: %w", err)
1186		}
1187		fmt.Fprintf(outW, "✓ Pushed to %s/%s\n", defaultMirrorRemote, pushBranch)
1188		if choice == configureSaveNewBranch {
1189			fmt.Fprintln(outW, "  Open a trail to merge it:")
1190			fmt.Fprintf(outW, "  %s/gh/%s/%s/trails/new?branch=%s\n", configureWebBaseURL(), url.PathEscape(owner), url.PathEscape(repo), url.QueryEscape(pushBranch))
1191		}
1192		return nil
1193	}
1194	
1195	func configureBranchProtected(ctx context.Context, owner, repo, branch string) (bool, error) {
1196		out, err := exec.CommandContext(ctx, "gh", "api", "repos/"+owner+"/"+repo+"/branches/"+url.PathEscape(branch), "--jq", ".protected").Output()
1197		if err != nil {
1198			return false, fmt.Errorf("check GitHub branch protection: %w", err)
1199		}
1200		protected, err := strconv.ParseBool(strings.TrimSpace(string(out)))
1201		if err != nil {
1202			return false, fmt.Errorf("parse GitHub branch protection: %w", err)
1203		}
1204		return protected, nil
1205	}
1206	
1207	func availableConfigureBranch(ctx context.Context, repoRoot string, now func() time.Time) (string, error) {
1208		candidates := []string{configureBranchBase, configureBranchBase + "-" + now().Format("20060102-150405")}
1209		for _, candidate := range candidates {
1210			_, err := gitRunner(ctx, repoRoot, "show-ref", "--verify", "--quiet", "refs/heads/"+candidate)
1211			if err == nil {
1212				continue // branch already exists
1213			}
1214			var exitErr *exec.ExitError
1215			if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
1216				return candidate, nil // show-ref uses 1 for a missing ref
1217			}
1218			return "", fmt.Errorf("check configuration branch %q: %w", candidate, err)
1219		}
1220		return "", errors.New("could not choose an unused configuration branch name")
1221	}
