	var cluster string
	cmd := &cobra.Command{
		Use:   "clone <repo> [target-dir]",
		Short: "Clone a mirrored repository",
		Long: "Clone a GitHub mirror by its `/gh/<owner>/<repo>` ref, or by a full " +
